-- All guest-entry fixtures remain in the guarded rolled-back policy transaction.
RESET ROLE;
INSERT INTO firstten_policy_test.ids(label,id) VALUES('guest_class_a','fc070000-0000-4000-8000-000000000001'),('guest_class_b','fc070000-0000-4000-8000-000000000002');
CREATE TABLE firstten_policy_test.guest_results(label text PRIMARY KEY,result jsonb);
GRANT SELECT,INSERT ON firstten_policy_test.guest_results TO authenticated,service_role;
GRANT USAGE ON SCHEMA firstten_policy_test TO service_role;
GRANT SELECT ON firstten_policy_test.ids TO service_role;
SELECT ok(NOT has_table_privilege('anon','firstten_private.guest_entry_links','SELECT,INSERT,UPDATE,DELETE'),'anonymous has no raw entry grants');
SELECT ok(NOT has_table_privilege('service_role','firstten_private.class_guest_sessions','SELECT,INSERT,UPDATE,DELETE'),'service key has fixed RPC, no raw session grants');
SELECT ok(NOT has_function_privilege('authenticated','public.exchange_guest_entry(text,text,text,text,text)','EXECUTE'),'account bearer cannot directly mint guest sessions');
SELECT ok(NOT has_function_privilege('anon','public.get_guest_session(text)','EXECUTE'),'anonymous direct session RPC denied');
SELECT ok(NOT has_function_privilege('service_role','firstten_private.resolve_guest(text)','EXECUTE'),'internal guest resolver not directly callable');
SELECT firstten_policy_test.set_actor('owner_a');SET LOCAL ROLE authenticated;
SELECT is(public.create_class(firstten_policy_test.id('guest_class_a'),gen_random_uuid(),jsonb_build_object('name','Fictional workshop A','mode','hackathon','instructions','Do not enter real names','accessExpiresAt',clock_timestamp()+interval '20 days','retentionDays',30))->>'ok','true','teacher creates real hackathon before activating guests');
INSERT INTO firstten_policy_test.guest_results SELECT 'entry_a',public.create_guest_entry(firstten_policy_test.id('guest_class_a'),7,2,'fc070000-0000-4000-8000-000000000011');
INSERT INTO firstten_policy_test.guest_results SELECT 'entry_pending',public.create_guest_entry(firstten_policy_test.id('guest_class_a'),7,2,gen_random_uuid());
INSERT INTO firstten_policy_test.guest_results SELECT 'entry_expired',public.create_guest_entry(firstten_policy_test.id('guest_class_a'),7,2,gen_random_uuid());
SELECT is((SELECT result->>'ok' FROM firstten_policy_test.guest_results WHERE label='entry_a'),'true','owner activates bounded class entry');
SELECT is(public.create_guest_entry(firstten_policy_test.id('guest_class_a'),7,2,'fc070000-0000-4000-8000-000000000011')->>'token',NULL,'entry creation retry cannot recover plaintext');
SELECT is(public.create_guest_entry(firstten_policy_test.id('guest_class_a'),8,2,'fc070000-0000-4000-8000-000000000011')->>'code','IDEMPOTENCY_CONFLICT','same entry request cannot change bounds');
SELECT is(public.create_guest_entry(firstten_policy_test.id('guest_class_a'),31,2,gen_random_uuid())->>'code','INVALID_INPUT','entry expiry bound enforced by SQL');
SELECT is(public.create_guest_entry(firstten_policy_test.id('guest_class_a'),7,201,gen_random_uuid())->>'code','INVALID_INPUT','entry capacity bound enforced by SQL');
SELECT is(public.set_class_teacher(firstten_policy_test.id('guest_class_a'),firstten_policy_test.id('teacher'),true,'Workshop co-teacher',0,gen_random_uuid())->>'ok','true','co-teacher authority remains explicit');
RESET ROLE;SELECT firstten_policy_test.set_actor('owner_b');SET LOCAL ROLE authenticated;
SELECT is(public.create_class(firstten_policy_test.id('guest_class_b'),gen_random_uuid(),jsonb_build_object('name','Fictional class B','mode','class','instructions','Other class','accessExpiresAt',clock_timestamp()+interval '20 days','retentionDays',30))->>'ok','true','second teacher owns distinct guest class');
INSERT INTO firstten_policy_test.guest_results SELECT 'entry_b',public.create_guest_entry(firstten_policy_test.id('guest_class_b'),7,1,gen_random_uuid());
SELECT is(public.list_guest_entries(firstten_policy_test.id('guest_class_a'))->>'code','NOT_FOUND','foreign teacher cannot enumerate entry links');
SELECT is(public.revoke_guest_entry(firstten_policy_test.id('guest_class_a'),(SELECT (result#>>'{data,id}')::uuid FROM firstten_policy_test.guest_results WHERE label='entry_a'))->>'code','NOT_FOUND','foreign teacher cannot revoke entry');
RESET ROLE;SELECT firstten_policy_test.set_actor('teacher');SET LOCAL ROLE authenticated;
SELECT is(public.create_guest_entry(firstten_policy_test.id('guest_class_a'),7,2,gen_random_uuid())->>'code','NOT_FOUND','co-teacher cannot activate entry authority');
RESET ROLE;SET LOCAL ROLE service_role;
INSERT INTO firstten_policy_test.guest_results SELECT 'a1',public.exchange_guest_entry('entry',(SELECT result->>'token' FROM firstten_policy_test.guest_results WHERE label='entry_a'),'Team Alpha','',repeat('1',64));
INSERT INTO firstten_policy_test.guest_results SELECT 'a2',public.exchange_guest_entry('entry',(SELECT result->>'token' FROM firstten_policy_test.guest_results WHERE label='entry_a'),'Team Beta','Alias B',repeat('2',64));
INSERT INTO firstten_policy_test.guest_results SELECT 'b1',public.exchange_guest_entry('entry',(SELECT result->>'token' FROM firstten_policy_test.guest_results WHERE label='entry_b'),'Other class team','',repeat('3',64));
SELECT is((SELECT result->>'ok' FROM firstten_policy_test.guest_results WHERE label='a1'),'true','no-account guest enters real team and principal');
SELECT is((SELECT result#>>'{data,teamAlias}' FROM firstten_policy_test.guest_results WHERE label='a1'),'Team Alpha','chosen team alias retained');
SELECT ok((SELECT result#>>'{data,principalAlias}' LIKE 'Learner %' FROM firstten_policy_test.guest_results WHERE label='a1'),'missing personal alias generated without required name/email');
SELECT is((SELECT result#>>'{data,aiEnabled}' FROM firstten_policy_test.guest_results WHERE label='a1'),'false','guest/class AI disabled');
SELECT is(public.exchange_guest_entry('entry',(SELECT result->>'token' FROM firstten_policy_test.guest_results WHERE label='entry_a'),'Extra','',repeat('4',64))->>'code','CAPACITY','bounded entry rejects excess team creation');
SELECT is(public.get_guest_session((SELECT result->>'token' FROM firstten_policy_test.guest_results WHERE label='entry_a'))->>'code','NOT_FOUND','public class code is never a session read grant');
SELECT is(public.exchange_guest_entry('team_return',(SELECT result->>'token' FROM firstten_policy_test.guest_results WHERE label='entry_a'),'','',repeat('5',64))->>'code','NOT_FOUND','class entry cannot masquerade as team return');
INSERT INTO firstten_policy_test.guest_results SELECT 'teammate',public.exchange_guest_entry('team_invite',(SELECT result#>>'{secrets,teamInvite}' FROM firstten_policy_test.guest_results WHERE label='a1'),'Ignored rename','Teammate',repeat('6',64));
SELECT is((SELECT result#>>'{data,teamId}' FROM firstten_policy_test.guest_results WHERE label='teammate'),(SELECT result#>>'{data,teamId}' FROM firstten_policy_test.guest_results WHERE label='a1'),'team invitation joins only its actual team');
SELECT isnt((SELECT result#>>'{data,principalId}' FROM firstten_policy_test.guest_results WHERE label='teammate'),(SELECT result#>>'{data,principalId}' FROM firstten_policy_test.guest_results WHERE label='a1'),'shared team invitation never recovers another private principal');
SELECT is((SELECT result#>>'{data,teamAlias}' FROM firstten_policy_test.guest_results WHERE label='teammate'),'Team Alpha','team invitation cannot rename team');
INSERT INTO firstten_policy_test.guest_results SELECT 'team_returned',public.exchange_guest_entry('team_return',(SELECT result#>>'{secrets,teamReturn}' FROM firstten_policy_test.guest_results WHERE label='a1'),'','Returning teammate',repeat('7',64));
SELECT isnt((SELECT result#>>'{data,principalId}' FROM firstten_policy_test.guest_results WHERE label='team_returned'),(SELECT result#>>'{data,principalId}' FROM firstten_policy_test.guest_results WHERE label='a1'),'team return also creates distinct private principal');
SELECT is(public.exchange_guest_entry('principal_recovery',(SELECT result#>>'{secrets,teamReturn}' FROM firstten_policy_test.guest_results WHERE label='a1'),'','',repeat('8',64))->>'code','NOT_FOUND','shared team return cannot call private recovery');
SELECT is(public.exchange_guest_entry('team_invite',(SELECT result#>>'{secrets,principalRecovery}' FROM firstten_policy_test.guest_results WHERE label='a1'),'','',repeat('9',64))->>'code','NOT_FOUND','private recovery cannot be interpreted as a shared invitation');
INSERT INTO firstten_policy_test.guest_results SELECT 'recovered',public.exchange_guest_entry('principal_recovery',(SELECT result#>>'{secrets,principalRecovery}' FROM firstten_policy_test.guest_results WHERE label='a1'),'Forged team','Forged alias',repeat('a',64));
SELECT is((SELECT result#>>'{data,principalId}' FROM firstten_policy_test.guest_results WHERE label='recovered'),(SELECT result#>>'{data,principalId}' FROM firstten_policy_test.guest_results WHERE label='a1'),'private recovery restores exact principal');
SELECT is(public.get_guest_session((SELECT result->>'sessionToken' FROM firstten_policy_test.guest_results WHERE label='a1'))->>'code','NOT_FOUND','private recovery invalidates original browser session');
SELECT is(public.exchange_guest_entry('principal_recovery',(SELECT result#>>'{secrets,principalRecovery}' FROM firstten_policy_test.guest_results WHERE label='a1'),'','',repeat('b',64))->>'code','NOT_FOUND','private recovery token is one-use');
SELECT is(public.get_guest_session((SELECT result->>'sessionToken' FROM firstten_policy_test.guest_results WHERE label='recovered'))->>'ok','true','new recovered session authorizes own scope');
INSERT INTO firstten_policy_test.guest_results SELECT 'buddy_recovery',public.manage_guest_session((SELECT result->>'sessionToken' FROM firstten_policy_test.guest_results WHERE label='teammate'),'rotate_principal_recovery');
SELECT is((SELECT result->>'ok' FROM firstten_policy_test.guest_results WHERE label='buddy_recovery'),'true','teammate rotates only their own private recovery');
SELECT is(public.manage_guest_session((SELECT result->>'sessionToken' FROM firstten_policy_test.guest_results WHERE label='teammate'),'read_other_private_principal')->>'code','INVALID_INPUT','no generic principal operation exists');
RESET ROLE;
SELECT ok(NOT EXISTS(SELECT 1 FROM auth.users u JOIN public.class_guest_principals p ON p.id=u.id WHERE p.class_id IN(firstten_policy_test.id('guest_class_a'),firstten_policy_test.id('guest_class_b'))),'guest admission creates no fake auth identities');
SELECT is((SELECT count(*) FROM public.projects WHERE id IN(SELECT id FROM public.class_teams WHERE class_id=firstten_policy_test.id('guest_class_a'))),0::bigint,'guest admission creates no fake account projects');
SELECT ok((SELECT bool_and(token_hash~'^[0-9a-f]{64}$') FROM firstten_private.class_guest_sessions WHERE class_id=firstten_policy_test.id('guest_class_a')),'guest sessions persist hashes only');
SELECT ok((SELECT token_hash=encode(sha256(convert_to(r.result->>'sessionToken','UTF8')),'hex') FROM firstten_private.class_guest_sessions s JOIN firstten_policy_test.guest_results r ON s.principal_id=(r.result#>>'{data,principalId}')::uuid WHERE r.label='recovered' AND s.revoked_at IS NULL),'saved session is the digest of its one-time secret');
SELECT ok((SELECT principal_id=(SELECT (result#>>'{data,principalId}')::uuid FROM firstten_policy_test.guest_results WHERE label='teammate') FROM firstten_private.guest_capabilities WHERE token_hash=encode(sha256(convert_to((SELECT result->>'token' FROM firstten_policy_test.guest_results WHERE label='buddy_recovery'),'UTF8')),'hex')),'teammate recovery remains bound to teammate principal');
SELECT ok((SELECT NOT(result#>'{data}' ?| ARRAY['roster','members','sessionToken','privateNotes','projects','contacts']) FROM firstten_policy_test.guest_results WHERE label='a1'),'guest projection has no roster or raw private sources');
-- Capacity exceptions preserve the outer rate counter while rolling back scope writes.
INSERT INTO public.class_guest_principals(class_id,team_id,issued_by,alias)
SELECT firstten_policy_test.id('guest_class_a'),(SELECT (result#>>'{data,teamId}')::uuid FROM firstten_policy_test.guest_results WHERE label='a2'),firstten_policy_test.id('owner_a'),'Capacity fixture '||n FROM generate_series(1,11)n;
SET LOCAL ROLE service_role;
SELECT is(public.exchange_guest_entry('team_invite',(SELECT result#>>'{secrets,teamInvite}' FROM firstten_policy_test.guest_results WHERE label='a2'),'','Over capacity',repeat('c',64))->>'code','CAPACITY','full team denies admission atomically');
RESET ROLE;
SELECT is((SELECT attempts FROM firstten_private.guest_admission_buckets WHERE bucket_hash=repeat('c',64) AND window_start=date_trunc('minute',clock_timestamp())),1,'failed capacity admission still consumes rate allowance');
SELECT is((SELECT count(*) FROM public.class_guest_principals WHERE team_id=(SELECT (result#>>'{data,teamId}')::uuid FROM firstten_policy_test.guest_results WHERE label='a2')),12::bigint,'failed admission leaves no extra principal');
UPDATE firstten_private.guest_entry_links SET created_at=clock_timestamp()-interval '2 days',expires_at=clock_timestamp()-interval '1 day' WHERE id=(SELECT (result#>>'{data,id}')::uuid FROM firstten_policy_test.guest_results WHERE label='entry_expired');
SET LOCAL ROLE service_role;
SELECT is(public.exchange_guest_entry('entry',(SELECT result->>'token' FROM firstten_policy_test.guest_results WHERE label='entry_expired'),'','',repeat('d',64))->>'code','NOT_FOUND','expired entry is unusable');
RESET ROLE;SELECT firstten_policy_test.set_actor('owner_a');SET LOCAL ROLE authenticated;
SELECT is(public.revoke_guest_entry(firstten_policy_test.id('guest_class_a'),(SELECT (result#>>'{data,id}')::uuid FROM firstten_policy_test.guest_results WHERE label='entry_pending'))->>'ok','true','owner revokes unused entry');
SELECT is(public.revoke_guest_scope(firstten_policy_test.id('guest_class_a'),(SELECT (result#>>'{data,teamId}')::uuid FROM firstten_policy_test.guest_results WHERE label='a2'),(SELECT (result#>>'{data,principalId}')::uuid FROM firstten_policy_test.guest_results WHERE label='a2'))->>'ok','true','owner revokes a real principal only within own team/class');
SELECT is(public.revoke_guest_scope(firstten_policy_test.id('guest_class_a'),(SELECT (result#>>'{data,teamId}')::uuid FROM firstten_policy_test.guest_results WHERE label='a1'))->>'ok','true','owner revokes whole team access');
SELECT is(jsonb_array_length(public.list_guest_teams(firstten_policy_test.id('guest_class_a'))#>'{data,items}'),2,'owner gets only their class safe team projection');
RESET ROLE;SET LOCAL ROLE service_role;
SELECT is(public.exchange_guest_entry('entry',(SELECT result->>'token' FROM firstten_policy_test.guest_results WHERE label='entry_pending'),'','',repeat('e',64))->>'code','NOT_FOUND','revoked public entry cannot admit');
SELECT is(public.get_guest_session((SELECT result->>'sessionToken' FROM firstten_policy_test.guest_results WHERE label='a2'))->>'code','NOT_FOUND','revoked principal session denied');
SELECT is(public.get_guest_session((SELECT result->>'sessionToken' FROM firstten_policy_test.guest_results WHERE label='recovered'))->>'code','NOT_FOUND','team revocation denies recovered private principal');
SELECT is(public.get_guest_session((SELECT result->>'sessionToken' FROM firstten_policy_test.guest_results WHERE label='teammate'))->>'code','NOT_FOUND','team revocation denies teammate session');
SELECT is(public.exchange_guest_entry('team_return',(SELECT result#>>'{secrets,teamReturn}' FROM firstten_policy_test.guest_results WHERE label='a1'),'','',repeat('f',64))->>'code','NOT_FOUND','team revocation invalidates shared return key');
SELECT is(public.get_guest_session((SELECT result->>'sessionToken' FROM firstten_policy_test.guest_results WHERE label='b1'))->>'ok','true','other class remains unaffected');
RESET ROLE;
-- Fill only fictional team history to the hard bound; rejection must leave its
-- still-valid private recovery and current session untouched.
INSERT INTO firstten_private.guest_capabilities(class_id,team_id,kind,token_hash,max_uses,expires_at)
SELECT firstten_policy_test.id('guest_class_b'),(SELECT (result#>>'{data,teamId}')::uuid FROM firstten_policy_test.guest_results WHERE label='b1'),'team_invite',encode(sha256(convert_to('history-fixture-'||n,'UTF8')),'hex'),1,clock_timestamp()+interval '1 day' FROM generate_series(1,253)n;
SET LOCAL ROLE service_role;
SELECT is(public.exchange_guest_entry('principal_recovery',(SELECT result#>>'{secrets,principalRecovery}' FROM firstten_policy_test.guest_results WHERE label='b1'),'','',repeat('8',64))->>'code','RECOVERY_UNAVAILABLE','terminal capability history refuses recovery before changing old credentials');
SELECT is(public.get_guest_session((SELECT result->>'sessionToken' FROM firstten_policy_test.guest_results WHERE label='b1'))->>'ok','true','recovery capacity failure preserves valid current session');
RESET ROLE;
SELECT ok((SELECT revoked_at IS NULL AND uses=0 FROM firstten_private.guest_capabilities WHERE token_hash=encode(sha256(convert_to((SELECT result#>>'{secrets,principalRecovery}' FROM firstten_policy_test.guest_results WHERE label='b1'),'UTF8')),'hex')),'recovery capacity failure leaves private recovery unconsumed');
SELECT is((SELECT count(*) FROM firstten_private.guest_capabilities WHERE team_id=(SELECT (result#>>'{data,teamId}')::uuid FROM firstten_policy_test.guest_results WHERE label='b1')),256::bigint,'capability history remains within hard bound');
INSERT INTO firstten_private.class_guest_sessions(class_id,team_id,principal_id,token_hash,created_at,expires_at)
SELECT firstten_policy_test.id('guest_class_b'),(result#>>'{data,teamId}')::uuid,(result#>>'{data,principalId}')::uuid,encode(sha256(convert_to(repeat('6',64),'UTF8')),'hex'),clock_timestamp()-interval '2 hours',clock_timestamp()-interval '1 hour' FROM firstten_policy_test.guest_results WHERE label='b1';
SET LOCAL ROLE service_role;
SELECT is(public.get_guest_session(repeat('6',64))->>'code','NOT_FOUND','expired session denied while class and principal remain active');
RESET ROLE;SELECT firstten_policy_test.set_actor('owner_b');SET LOCAL ROLE authenticated;
SELECT is(public.revoke_guest_scope(firstten_policy_test.id('guest_class_b'),(SELECT (result#>>'{data,teamId}')::uuid FROM firstten_policy_test.guest_results WHERE label='a1'))->>'code','NOT_FOUND','wrong class/team capability cannot revoke another team');
SELECT is(public.set_class_archived(firstten_policy_test.id('guest_class_b'),true,1,gen_random_uuid())->>'ok','true','class owner closes guest space');
RESET ROLE;SET LOCAL ROLE service_role;
SELECT is(public.get_guest_session((SELECT result->>'sessionToken' FROM firstten_policy_test.guest_results WHERE label='b1'))->>'code','NOT_FOUND','class closure denies existing guest session');
SELECT is(public.exchange_guest_entry('principal_recovery',(SELECT result#>>'{secrets,principalRecovery}' FROM firstten_policy_test.guest_results WHERE label='b1'),'','',repeat('0',64))->>'code','NOT_FOUND','class closure denies private recovery too');
RESET ROLE;
INSERT INTO firstten_private.guest_admission_buckets(bucket_hash,window_start,attempts) VALUES(repeat('7',64),date_trunc('minute',clock_timestamp()),120) ON CONFLICT(bucket_hash,window_start)DO UPDATE SET attempts=120;
SET LOCAL ROLE service_role;
SELECT is(public.exchange_guest_entry('entry',repeat('0',64),'','',repeat('7',64))->>'code','RATE_LIMITED','client rate cap applies even for invalid codes');
RESET ROLE;SELECT firstten_policy_test.set_actor('student');SET LOCAL ROLE authenticated;
SELECT is(public.list_guest_teams(firstten_policy_test.id('guest_class_a'))->>'code','NOT_FOUND','student account cannot enumerate guest teams');
SELECT is(firstten_policy_test.attempt('SELECT * FROM firstten_private.class_guest_sessions'),'error:42501','browser bearer cannot bypass cookie service adapter');
RESET ROLE;SET LOCAL ROLE anon;
SELECT is(firstten_policy_test.attempt($case$SELECT public.exchange_guest_entry('entry',repeat('0',64),'','',repeat('0',64))$case$),'error:42501','direct anonymous RPC bypass denied');
RESET ROLE;

-- The global limiter remains effective with a fresh client identity.
INSERT INTO firstten_private.guest_admission_buckets(bucket_hash,window_start,attempts) VALUES(encode(sha256(convert_to('global-guest-entry','UTF8')),'hex'),date_trunc('minute',clock_timestamp()),500) ON CONFLICT(bucket_hash,window_start)DO UPDATE SET attempts=500;
SET LOCAL ROLE service_role;
SELECT is(public.exchange_guest_entry('entry',repeat('0',64),'','',repeat('5',64))->>'code','RATE_LIMITED','global rate cap cannot be bypassed by changing client identity');
RESET ROLE;
